        "Det är en växelpreposition: på frågan Wo? (var?) följer dativ (an der Tür), på frågan Wohin? (vart?) ackusativ (an die Tür). Sammandragningar: an dem → am, an das → ans.",
        "Om tid används an med veckodagar och delar av dygnet: am Montag, am Abend. Många verb kräver an + ackusativ: an dich denken (tänka på dig)."
