        "Den påverkar inte ordföljden: aber står på position 0, och verbet kommer efter den precis som i en vanlig huvudsats. Före aber sätter man normalt komma.",
        "I talspråk kan aber också vara en partikel som förstärker förvåning: Das ist aber schön! (Vad fint det är!). Som svar betyder Aber gern! ”ja, gärna!”."
