      "explanation": [
        "Grundidé: bleiben betyder att stanna kvar på en plats eller i ett tillstånd: Ich bleibe zu Hause (jag stannar hemma), Das Wetter bleibt schön (vädret förblir fint).",
        "Former: er bleibt, blieb, ist geblieben. I perfekt är hjälpverbet sein, inte haben: Ich bin zu Hause geblieben.",
        "Efter bleiben kan en plats eller ett adjektiv stå; med infinitiv bildar det uttryck: stehen bleiben (stanna, bli stående), sitzen bleiben (bli sittande)."
      ],
      "examples": [
        {
          "de": "Ich bleibe heute zu Hause.",
          "lv": "Jag stannar hemma i dag."
        },
        {
          "de": "Wie lange bleibst du in Berlin?",
          "lv": "Hur länge stannar du i Berlin?"
        },
        {
          "de": "Das Wetter bleibt schön.",
          "lv": "Vädret förblir fint."
        },
        {
          "de": "Wir sind drei Tage geblieben.",
          "lv": "Vi stannade i tre dagar."
        },
        {
          "de": "Bleib bitte ruhig!",
          "lv": "Snälla, håll dig lugn!"
        }
      ],
      "comparison": [
        {
          "word": "wohnen",
          "meaning": "bo",
          "example": "Ich wohne in Riga. – Jag bor i Riga."
        },
        {
          "word": "warten",
          "meaning": "vänta",
          "example": "Ich warte auf den Bus. – Jag väntar på bussen."
        },
        {
          "word": "sein",
          "meaning": "vara",
          "example": "Ich bin zu Hause. – Jag är hemma."
        }
      ],
      "tip": [
        "I perfekt säger du ist geblieben, inte ”hat geblieben”.",
        "Bleib! är imperativformen: Bleib hier!"
      ],
      "important": [
        "Bleiben är ett starkt verb: blieb, ist geblieben.",
        "Blanda inte ihop det med wohnen: där du bor heter wohnen; där du vistas en tid heter bleiben."
      ],
