      "explanation": [
        "Grundidé: ein är den obestämda artikeln: ein Mann, eine Frau, ein Kind. Den visar att substantivet är nytt eller inte närmare bestämt (någon man, en kvinna).",
        "Maskulinum och neutrum har ein, femininum eine. I ackusativ har maskulinum einen: Ich habe einen Bruder. I dativ: einem (maskulinum/neutrum), einer (femininum). I plural finns ingen obestämd artikel; vid negation används kein.",
        "Ein är också räkneordet ”en, ett”: Ich habe nur ein Kind. Då uttalas det med betoning."
      ],
      "examples": [
        {
          "de": "Ich habe einen Bruder.",
          "lv": "Jag har en bror."
        },
        {
          "de": "Das ist eine gute Idee.",
          "lv": "Det är en bra idé."
        },
        {
          "de": "Er kauft ein Auto.",
          "lv": "Han köper en bil."
        },
        {
          "de": "Ein Kind spielt im Garten.",
          "lv": "Ett barn leker i trädgården."
        },
        {
          "de": "Ich habe keinen Hund.",
          "lv": "Jag har ingen hund."
        }
      ],
      "comparison": [
        {
          "word": "kein",
          "meaning": "ingen, inte någon",
          "example": "Ich habe kein Auto. – Jag har ingen bil."
        },
        {
          "word": "der",
          "meaning": "bestämd artikel",
          "example": "Der Mann kommt. – Mannen kommer."
        },
        {
          "word": "eins",
          "meaning": "ett (vid räkning)",
          "example": "Eins, zwei, drei. – Ett, två, tre."
        }
      ],
      "tip": [
        "I plural finns ingen obestämd artikel: Ich habe Bücher.",
        "Vid negation används kein: kein Mann, keine Frau."
      ],
      "important": [
        "Ein är inte bara en artikel – med betoning är det räkneordet ”en, ett”.",
        "I ackusativ har ett maskulint substantiv einen, inte ”ein”: Ich sehe einen Mann."
      ],
