      "layout": "standardStudy",
      "translation": "hel • helt",
      "explanation": [
        "Grundidé: som adjektiv betyder ganz hel, all, full: der ganze Tag (hela dagen), die ganze Familie (hela familjen), das ganze Buch (hela boken). Det böjs som ett vanligt adjektiv.",
        "Som adverb betyder ganz ”helt, alldeles, ganska”: ganz neu (helt ny), ganz einfach (alldeles enkelt), ganz gut (ganska bra).",
        "Framför ortnamn utan artikel böjs ganz inte: ganz Europa (hela Europa), ganz Lettland (hela Lettland)."
      ],
      "examples": [
        {
          "de": "Ich habe den ganzen Tag gearbeitet.",
          "lv": "Jag har arbetat hela dagen."
        },
        {
          "de": "Sie isst die ganze Pizza.",
          "lv": "Hon äter upp hela pizzan."
        },
        {
          "de": "Das ist ganz einfach.",
          "lv": "Det är alldeles enkelt."
        },
        {
          "de": "Die ganze Familie kommt zum Fest.",
          "lv": "Hela familjen kommer till festen."
        },
        {
          "de": "Das Buch ist ganz neu.",
          "lv": "Boken är helt ny."
        }
      ],
