      "translation": "morföräldrar • farföräldrar",
      "explanation": [
        "Grundtanke: die Großeltern är ett substantiv i plural som betyder far- och morföräldrar – farmor/mormor och farfar/morfar tillsammans: Meine Großeltern wohnen auf dem Land.",
        "Var för sig: der Großvater (farfar/morfar), die Großmutter (farmor/mormor); i vardagsspråk der Opa och die Oma. Någon singularform av Großeltern finns inte.",
        "I dativ plural ändras formen inte (ordet slutar redan på -n): bei den Großeltern, mit den Großeltern."
      ],
      "examples": [
        {
          "de": "Meine Großeltern wohnen auf dem Land.",
          "lv": "Mina far- och morföräldrar bor på landet."
        },
        {
          "de": "Wir besuchen am Sonntag unsere Großeltern.",
          "lv": "På söndag hälsar vi på våra far- och morföräldrar."
        },
        {
          "de": "Hast du noch Großeltern?",
          "lv": "Har du några far- eller morföräldrar kvar?"
        },
        {
          "de": "Er verbringt die Ferien bei den Großeltern.",
          "lv": "Han tillbringar lovet hos sina far- och morföräldrar."
        },
        {
          "de": "Die Großeltern meiner Mutter leben in Riga.",
          "lv": "Min mammas far- och morföräldrar bor i Riga."
        }
      ],
      "comparison": [
        {
          "word": "die Eltern",
          "meaning": "föräldrar",
          "example": "Meine Eltern arbeiten. – Mina föräldrar arbetar."
        },
        {
          "word": "der Opa",
          "meaning": "farfar eller morfar",
          "example": "Mein Opa liest gern. – Min morfar läser gärna."
        },
        {
          "word": "die Oma",
          "meaning": "farmor eller mormor",
          "example": "Meine Oma kocht gut. – Min mormor lagar god mat."
        }
      ],
      "tip": [
        "Oma och Opa är vardagliga ord för farmor/mormor och farfar/morfar.",
        "Großeltern är plural, därför står verbet i plural: Die Großeltern kommen."
      ],
      "important": [
        "Großeltern är inte samma sak som Eltern – föräldrar heter Eltern.",
        "Om en enda farmor eller morfar används inte Großeltern: då heter det Großmutter eller Großvater."
      ],
