      "translation": "ni • henne",
      "explanation": [
        "Grundtanke: ihr är ett kort men mångtydigt ord. 1) Personligt pronomen i nominativ: ihr = ni (flera personer som man säger du till): Ihr seid nett. 2) Dativ av sie (hon): Ich helfe ihr – jag hjälper henne. 3) Possessivt pronomen: ihr Bruder – hennes/deras bror.",
        "Possessivt ihr böjs som ein: ihr Buch, ihre Mutter, ihren Vater, ihrem Kind. Det kan betyda ”hennes” (om en kvinna) eller ”deras” (om flera).",
        "Skillnad: ihr (ni, flera man säger du till) ≠ Sie (artigt ni, alltid med stor bokstav) ≠ Ihr/Ihnen (artigt: er/ert, till er)."
      ],
      "examples": [
        {
          "de": "Ihr seid heute spät.",
          "lv": "Ni är sena i dag."
        },
        {
          "de": "Kommt ihr morgen zur Party?",
          "lv": "Kommer ni på festen i morgon?"
        },
        {
          "de": "Ich gebe ihr das Buch.",
          "lv": "Jag ger henne boken."
        },
        {
          "de": "Ich helfe ihr beim Kochen.",
          "lv": "Jag hjälper henne med matlagningen."
        },
        {
          "de": "Ihr Bruder wohnt in Riga.",
          "lv": "Hennes bror bor i Riga."
        }
      ],
      "comparison": [
        {
          "word": "du",
          "meaning": "du (en person)",
          "example": "Kommst du mit? – Följer du med?"
        },
        {
          "word": "Sie",
          "meaning": "ni (artigt)",
          "example": "Wie heißen Sie? – Vad heter ni?"
        },
        {
          "word": "Ihnen",
          "meaning": "er, till er (artigt)",
          "example": "Ich helfe Ihnen gern. – Jag hjälper er gärna."
        }
      ],
      "tip": [
        "Om du säger du till två eller flera personer använder du ihr + verb med ändelsen -t: ihr habt, ihr kommt.",
        "Dativformen ihr känner du igen på verbet: helfen, geben, danken, gehören styr dativ."
      ],
      "important": [
        "Ihr (ni, nominativ) skrivs med liten bokstav mitt i meningen; artigt Ihr/Ihnen skrivs alltid med stor bokstav.",
        "Använd inte ihr för en enda person – en person är du, flera är ihr."
      ],
