      "translation": "låta • lämna",
      "explanation": [
        "Grundtanke: lassen är ett verb med många betydelser: 1) lämna (någonstans): Ich lasse die Tasche hier; 2) låta, tillåta: Meine Eltern lassen mich gehen; 3) låta göra något (vanligen av någon annan): Ich lasse das Auto reparieren.",
        "Former: ich lasse, du lässt, er lässt; preteritum ließ, perfekt hat gelassen. Med infinitiv är perfekt hat lassen (inte gelassen): Er hat mich gehen lassen. Imperativ: Lass! / Lasst uns! (låt oss …).",
        "Med ackusativ: etwas lassen; med infinitiv (utan zu): jemanden etwas tun lassen. Vanligt: Lass mich in Ruhe! – Låt mig vara i fred!"
      ],
      "examples": [
        {
          "de": "Ich lasse die Tasche hier.",
          "lv": "Jag lämnar väskan här."
        },
        {
          "de": "Lass das bitte auf dem Tisch.",
          "lv": "Lämna det på bordet, är du snäll."
        },
        {
          "de": "Meine Eltern lassen mich gehen.",
          "lv": "Mina föräldrar låter mig gå."
        },
        {
          "de": "Lass mich in Ruhe!",
          "lv": "Låt mig vara i fred!"
        },
        {
          "de": "Er lässt sein Auto reparieren.",
          "lv": "Han låter reparera sin bil."
        }
      ],
      "comparison": [
        {
          "word": "verlassen",
          "meaning": "lämna, överge",
          "example": "Er verlässt die Stadt. – Han lämnar staden."
        },
        {
          "word": "erlauben",
          "meaning": "tillåta",
          "example": "Mein Vater erlaubt es. – Min pappa tillåter det."
        },
        {
          "word": "zurücklassen",
          "meaning": "lämna kvar (bakom sig)",
          "example": "Er lässt den Hund zurück. – Han lämnar kvar hunden."
        }
      ],
      "tip": [
        "Stamformer: lassen – ließ – hat gelassen; i 2:a och 3:e person lässt.",
        "Lassen + infinitiv uttrycker ”låta (någon) göra”: Ich lasse mir die Haare schneiden – jag klipper mig (jag låter frisören klippa håret)."
      ],
      "important": [
        "Lassen och verlassen är olika: lassen – lämna/låta, verlassen – lämna en plats eller överge någon.",
        "Om lassen står tillsammans med en infinitiv används hat lassen i perfekt (den så kallade Ersatzinfinitiv-formen), inte hat gelassen."
      ],
