      "translation": "säker • säkert",
      "explanation": [
        "Grundidé: sicher är både adjektiv och adverb. Som adjektiv betyder det säker (utan fara: ein sicherer Weg) eller övertygad (Ich bin sicher). Som adverb betyder det säkert eller naturligtvis: Er kommt sicher.",
        "Uttrycket sich (Dat) sicher sein betyder att vara säker på sin sak: Ich bin mir sicher. Komparation: sicherer, am sichersten; substantivet är die Sicherheit.",
        "Sicher i början av en mening kan också vara ett svar: Sicher! — Naturligtvis!"
      ],
      "examples": [
        {
          "de": "Der Weg ist nachts nicht sicher.",
          "lv": "Vägen är inte säker på natten."
        },
        {
          "de": "Ich bin mir ganz sicher.",
          "lv": "Jag är helt säker."
        },
        {
          "de": "Er kommt sicher heute noch.",
          "lv": "Han kommer säkert redan i dag."
        },
        {
          "de": "Das Kind fährt schon sicher Fahrrad.",
          "lv": "Barnet cyklar redan säkert."
        },
        {
          "de": "Sicher, ich helfe dir gern.",
          "lv": "Visst, jag hjälper dig gärna."
        }
      ],
      "comparison": [
        {
          "word": "bestimmt",
          "meaning": "säkert, bestämt",
          "example": "Er kommt bestimmt. – Han kommer säkert."
        },
        {
          "word": "vielleicht",
          "meaning": "kanske",
          "example": "Vielleicht kommt er. – Han kanske kommer."
        },
        {
          "word": "gefährlich",
          "meaning": "farlig",
          "example": "Der Weg ist gefährlich. – Vägen är farlig."
        }
      ],
      "tip": [
        "Med sicher sein används ofta mir/dir: Ich bin mir sicher — det låter naturligare än bara Ich bin sicher.",
        "Kom ihåg motsatsen: sicher – unsicher (osäker)."
      ],
      "important": [
        "Sicher som adverb uttrycker stor sannolikhet, men inte alltid absolut visshet.",
        "Blanda inte ihop sicher med vielleicht: vielleicht betyder bara ”kanske”."
      ],
